<body>
<div class="wrap">
  <nav>
    <div class="brand">WastedToken <b>Mint</b></div>
    <div class="navlinks"><a href="#about">The mint</a><a href="#collection">Editions</a><a href="#collection">Acquire</a></div>
  </nav>

  <header>
    <div class="hero-copy">
      <div class="eyebrow">Tangible proof of online legend</div>
      <h1>Spend your <span>myth.</span></h1>
      <p>Hand-finished challenge coins for the gloriously overcommitted. Every piece is struck, numbered, and made to outlive the post that inspired it.</p>
    </div>
    <div class="coin-stage">
      <canvas id="coin-hero" aria-label="Rotating WastedToken Mint challenge coin"></canvas>
      <div class="hero-note"><span>01 / rotating archive specimen</span><span>Brass · 42mm · reeded edge</span></div>
    </div>
  </header>

  <section id="about">
    <div class="split">
      <div>
        <div class="kicker">The mint</div>
        <h2>Made for the lore.</h2>
        <div class="stamp">WT</div>
      </div>
      <div>
        <p class="lede">The internet forgets by breakfast. Metal has better manners.</p>
        <p class="copy">WastedToken Mint turns magnificent detours, improbable victories, and high-grade nonsense into heirloom-weight physical currency. Our collectible challenge coins are designed in tiny runs, sculpted in relief, and struck with the kind of unnecessary care usually reserved for national treasure.</p>
        <p class="copy">Each edition carries a denomination, a mint mark, and enough tactile detail to make your desk feel like a sovereign nation. No utility promised. Immense emotional collateral guaranteed.</p>
      </div>
    </div>
  </section>

  <section id="collection">
    <div class="collection-head">
      <div><div class="kicker">Issue one / 2025</div><h2>The first four.</h2></div>
      <p>Four materials. One beautifully unserious economy. Available editions are individually numbered and ship in archival black cartons.</p>
    </div>
    <div class="grid">
      <div class="edition" data-edition="bronze" data-state="available">
        <canvas class="edition-canvas" aria-label="Bronze coin"></canvas>
        <small>Edition 01 · 800 struck</small><h3>Bronze</h3>
        <div class="meta">A warm, old-world alloy with a fresh bad idea.</div>
        <div class="state">Available now</div><br>
        <button class="buy">Add to cart</button>
      </div>
      <div class="edition" data-edition="silver" data-state="available">
        <canvas class="edition-canvas" aria-label="Silver coin"></canvas>
        <small>Edition 02 · 500 struck</small><h3>Silver</h3>
        <div class="meta">Cool-toned proof for collectors with receipts.</div>
        <div class="state">Available now</div><br>
        <button class="buy">Add to cart</button>
      </div>
      <div class="edition sold" data-edition="gold" data-state="sold-out">
        <canvas class="edition-canvas" aria-label="Gold coin"></canvas>
        <small>Edition 03 · 111 struck</small><h3>Gold</h3>
        <div class="meta">The gilded original. It disappeared with dignity.</div>
        <div class="unavailable"><div class="state">Sold Out</div></div>
      </div>
      <div class="edition soon" data-edition="black" data-state="coming-soon">
        <canvas class="edition-canvas" aria-label="Black obsidian coin"></canvas>
        <small>Edition 04 · scheduled</small><h3>Black</h3>
        <div class="meta">Obsidian PVD, blackened relief, zero apologies.</div>
        <div class="unavailable"><div class="state">Minting Winter 2025</div></div>
      </div>
    </div>
  </section>
  <footer>© WastedToken Mint · Legal tender only in the kingdom of excellent decisions.</footer>
</div>

<script>
(() => {
  const canvas = document.getElementById('coin-hero');
  const ctx = canvas.getContext('2d');
  let paused = false, raf = 0, currentT = 0;

  function resizeCanvas(c, h) {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    const w = Math.round(c.clientWidth * dpr), hh = Math.round(h * dpr);
    if (c.width !== w || c.height !== hh) { c.width = w; c.height = hh; }
    return dpr;
  }
  function poly(c, points, fill, stroke) {
    c.beginPath(); points.forEach((p,i)=>i?c.lineTo(p[0],p[1]):c.moveTo(p[0],p[1])); c.closePath();
    if(fill){c.fillStyle=fill;c.fill()} if(stroke){c.strokeStyle=stroke;c.stroke()}
  }
  function circlePath(c,r) { c.beginPath(); c.arc(0,0,r,0,Math.PI*2); }

  function renderHero(t) {
    resizeCanvas(canvas, 510);
    const W=canvas.width,H=canvas.height;
    ctx.setTransform(1,0,0,1,0,0);
    ctx.fillStyle='#101317'; ctx.fillRect(0,0,W,H);

    const R=Math.min(W*.193,H*.355), T=R*.125;
    const cx=W*.5, cy=H*.505;
    const yaw=t*Math.PI*2;
    const pitch=.46*Math.sin(t*Math.PI*2 + .38);
    const sy=Math.sin(yaw), cyaw=Math.cos(yaw), sp=Math.sin(pitch), cp=Math.cos(pitch);
    const normalZ=cyaw*cp;
    const nearest = normalZ >= 0 ? T : -T;
    const far = -nearest;

    function P(x,y,z) {
      return [cx + cyaw*x + sy*z, cy + sp*(-sy*x+cyaw*z) + cp*y];
    }
    const seg=112;
    const farPts=[], nearPts=[];
    for(let i=0;i<seg;i++){
      const a=i/seg*Math.PI*2;
      farPts.push(P(Math.cos(a)*R,Math.sin(a)*R,far));
      nearPts.push(P(Math.cos(a)*R,Math.sin(a)*R,nearest));
    }
    // Cylindrical wall with individual reeded ridges.
    for(let i=0;i<seg;i++){
      const j=(i+1)%seg, a=(i+.5)/seg*Math.PI*2;
      const light=.5+.5*Math.cos(a-.65)*.70+.18*Math.sin(yaw+a);
      const ridge=(i%2===0?1:.68);
      const lum=Math.max(18,Math.min(83,25+light*53))*ridge;
      poly(ctx,[farPts[i],farPts[j],nearPts[j],nearPts[i]],`hsl(38 30% ${lum}%)`);
    }
    ctx.lineWidth=Math.max(1,W/850);
    for(let i=0;i<seg;i+=2){
      ctx.strokeStyle='rgba(11,9,5,.43)';
      ctx.beginPath();ctx.moveTo(farPts[i][0],farPts[i][1]);ctx.lineTo(nearPts[i][0],nearPts[i][1]);ctx.stroke();
    }

    function transformed(z, artworkFlip, draw) {
      ctx.save();
      const e=P(0,0,z);
      ctx.setTransform(cyaw,sp*sy,0,cp,e[0],e[1]);
      if(artworkFlip) ctx.scale(-1,1);
      draw();
      ctx.restore();
    }
    const isFront=normalZ>=0;
    transformed(nearest, !isFront, () => {
      // Outer raised metal rim
      const move = Math.sin(yaw*1.17 + pitch*1.8)*R*.52;
      let g=ctx.createLinearGradient(-R,0,R,0);
      g.addColorStop(0,'#382515'); g.addColorStop(.20,'#b27a35');
      g.addColorStop(.42,'#f5d18a'); g.addColorStop(.51,'#fff2be');
      g.addColorStop(.59,'#9b6428'); g.addColorStop(.8,'#d0994a');g.addColorStop(1,'#3b2414');
      circlePath(ctx,R);ctx.fillStyle=g;ctx.fill();
      ctx.strokeStyle='#20140c';ctx.lineWidth=3;ctx.stroke();
      circlePath(ctx,R-8);ctx.strokeStyle='rgba(255,241,184,.72)';ctx.lineWidth=2;ctx.stroke();

      circlePath(ctx,R-18);ctx.save();ctx.clip();
      let base=ctx.createRadialGradient(move,-R*.20,R*.05,0,0,R*1.1);
      if(isFront){
        base.addColorStop(0,'#fff0a9');base.addColorStop(.10,'#d9a14d');base.addColorStop(.38,'#70421e');
        base.addColorStop(.72,'#c18335');base.addColorStop(1,'#3a2114');
      } else {
        base.addColorStop(0,'#e3bd73');base.addColorStop(.13,'#895127');base.addColorStop(.43,'#30211d');
        base.addColorStop(.72,'#885027');base.addColorStop(1,'#1d1717');
      }
      ctx.fillStyle=base;ctx.fillRect(-R,-R,R*2,R*2);
      let rake=ctx.createLinearGradient(move-R*.32,-R,move+R*.32,R);
      rake.addColorStop(0,'rgba(255,255,255,0)');rake.addColorStop(.43,'rgba(255,243,184,.03)');
      rake.addColorStop(.51,'rgba(255,252,221,.83)');rake.addColorStop(.59,'rgba(255,216,121,.09)');rake.addColorStop(1,'rgba(255,255,255,0)');
      ctx.fillStyle=rake;ctx.fillRect(-R,-R,R*2,R*2);ctx.restore();
      circlePath(ctx,R-18);ctx.strokeStyle='rgba(19,10,5,.8)';ctx.lineWidth=3;ctx.stroke();

      // Fine inner rings
      [R-29,R-38].forEach((r,i)=>{circlePath(ctx,r);ctx.strokeStyle=i?'rgba(247,204,119,.25)':'rgba(22,12,5,.7)';ctx.lineWidth=i?1.2:2;ctx.stroke()});
      ctx.fillStyle='rgba(255,228,157,.74)';
      ctx.font='bold 8px Arial';ctx.textAlign='center';ctx.textBaseline='middle';
      if(isFront){
        ctx.fillText('W A S T E D   •   T O K E N   •   M I N T',0,-R+29);
        ctx.fillText('PHYSICAL PROOF OF DIGITAL LORE',0,R-29);
      } else {
        ctx.fillText('VALID FOR ONE GLORIOUS DETOUR',0,-R+29);
        ctx.fillText('WASTEDTOKEN MINT • ISSUE 01',0,R-29);
      }

      function raised(draw) {
        ctx.save();ctx.translate(2.5,3);ctx.globalAlpha=.7;ctx.strokeStyle='#260f05';ctx.fillStyle='#260f05';draw();ctx.restore();
        ctx.save();ctx.translate(-1.3,-1.7);ctx.strokeStyle='#ffe4a1';ctx.fillStyle='#f4c574';draw();ctx.restore();
      }
      if(isFront){
        raised(()=>{
          ctx.lineWidth=9;ctx.lineJoin='round';ctx.beginPath();
          ctx.moveTo(-57,-40);ctx.lineTo(-31,45);ctx.lineTo(0,-13);ctx.lineTo(31,45);ctx.lineTo(57,-40);
          ctx.stroke();
          ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-48,-43);ctx.lineTo(-25,26);ctx.lineTo(0,-28);ctx.lineTo(25,26);ctx.lineTo(48,-43);ctx.stroke();
        });
        ctx.font='bold 20px Georgia';ctx.textAlign='center';ctx.fillText('WT',0,76);
        ctx.font='bold 9px Arial';ctx.fillText('MINT MARK • 2025',0,91);
      } else {
        raised(()=>{
          ctx.textAlign='center';ctx.font='bold 34px Georgia';ctx.fillText('10,000',0,-7);
          ctx.font='bold 13px Arial';ctx.fillText('TOKENS',0,20);
          ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-54,35);ctx.lineTo(54,35);ctx.stroke();
          ctx.font='bold 10px Arial';ctx.fillText('NO REDEMPTION. ALL GLORY.',0,53);
        });
        ctx.beginPath();ctx.moveTo(0,-65);ctx.lineTo(9,-50);ctx.lineTo(27,-47);ctx.lineTo(14,-34);ctx.lineTo(17,-16);ctx.lineTo(0,-25);ctx.lineTo(-17,-16);ctx.lineTo(-14,-34);ctx.lineTo(-27,-47);ctx.lineTo(-9,-50);ctx.closePath();
        ctx.fillStyle='#f4c574';ctx.fill();
      }
    });

    // tiny contact shadow gives depth without adding anything but the coin
    ctx.setTransform(1,0,0,1,0,0);
  }

  function animate(now) {
    if(paused) return;
    currentT=(now%9000)/9000;
    renderHero(currentT);
    raf=requestAnimationFrame(animate);
  }

  function drawEdition(c, type) {
    resizeCanvas(c, 214);
    const x=c.getContext('2d'),W=c.width,H=c.height;
    x.clearRect(0,0,W,H);
    const R=Math.min(W,H)*.33,cx=W*.5,cy=H*.5, yaw=-.34,pitch=.22,T=R*.13;
    const palette={
      bronze:['#482714','#b56b31','#f3c272','#29150d'],
      silver:['#273039','#899baa','#eff8f0','#182027'],
      gold:['#5b3510','#c88a20','#fff0a1','#332008'],
      black:['#07090b','#27313a','#93a4a2','#020304']
    }[type];
    function p(a,z){return [cx+Math.cos(yaw)*Math.cos(a)*R+Math.sin(yaw)*z,cy+Math.sin(pitch)*(-Math.sin(yaw)*Math.cos(a)*R)+Math.cos(pitch)*Math.sin(a)*R]}
    const near=T,far=-T, n=48, A=[],B=[];
    for(let i=0;i<n;i++){A.push(p(i/n*Math.PI*2,far));B.push(p(i/n*Math.PI*2,near))}
    for(let i=0;i<n;i++){let j=(i+1)%n;poly(x,[A[i],A[j],B[j],B[i]],i%2?palette[0]:palette[1])}
    x.save();x.setTransform(Math.cos(yaw),Math.sin(pitch)*Math.sin(yaw),0,Math.cos(pitch),cx+Math.sin(yaw)*near,cy+Math.sin(pitch)*Math.cos(yaw)*near);
    let g=x.createRadialGradient(-R*.3,-R*.35,R*.05,0,0,R);g.addColorStop(0,palette[2]);g.addColorStop(.26,palette[1]);g.addColorStop(1,palette[3]);
    circlePath(x,R);x.fillStyle=g;x.fill();x.strokeStyle='rgba(255,255,255,.45)';x.lineWidth=2;x.stroke();
    circlePath(x,R-10);x.strokeStyle='rgba(0,0,0,.55)';x.lineWidth=2;x.stroke();
    circlePath(x,R-20);x.strokeStyle='rgba(255,255,255,.25)';x.lineWidth=1;x.stroke();
    x.fillStyle=palette[2];x.textAlign='center';x.textBaseline='middle';x.font=`bold ${R*.43}px Georgia`;x.fillText('WT',0,-3);
    x.font=`bold ${R*.12}px Arial`;x.fillText('WASTEDTOKEN',0,R*.37);
    x.restore();
  }

  document.querySelectorAll('.edition').forEach(el => drawEdition(el.querySelector('canvas'),el.dataset.edition));
  window.addEventListener('resize',()=>{renderHero(currentT);document.querySelectorAll('.edition').forEach(el=>drawEdition(el.querySelector('canvas'),el.dataset.edition))});
  document.querySelectorAll('button.buy').forEach(b=>b.addEventListener('click',()=>{b.textContent='Added to cart';b.disabled=true;}));

  window.demo = {
    canvas,
    setTime(t) {
      currentT=Math.max(0,Math.min(1,Number(t)||0));
      renderHero(currentT);
    },
    pause() {
      paused=true;
      if(raf) cancelAnimationFrame(raf);
    }
  };
  renderHero(0);
  raf=requestAnimationFrame(animate);
})();
</script>
</body>
</html>
